const response = $input.first().json;
const parsed = $('Parse Input').first().json;
let classification = { mode: 'chat', intent: 'help' };
try { const content = response.message?.content; if (content) classification = JSON.parse(content); } catch (e) {}
return [{ json: { ...parsed, mode: classification.mode || 'chat', intent: classification.intent || 'help', extractedProjectSlug: classification.projectSlug || null } }];

const input = $input.first().json;
const intent = input.intent || 'help';
const projectSlug = input.projectSlug || input.extractedProjectSlug;
let response = { agent: 'Solution Architect', stage: 'solution-architecture', intent: intent, action: 'direct_response', query: null };
switch(intent) {
  case 'help':
    response.content = '# Solution Architecture Pipeline\n\n## Commands\n| Command | Description |\n|---------|-------------|\n| help | Show help |\n| status | Check job status |\n| artifacts | List artifacts |\n| jobs | List recent jobs |\n| list | List projects |';
    response.message = 'Help';
    break;
  case 'status': case 'jobs':
    response.action = 'query_db';
    response.query = projectSlug ? `SELECT j.id, p.slug as project, j.stage, j.status, j.created_at, j.completed_at FROM architecture.jobs j JOIN architecture.projects p ON j.project_id = p.id WHERE j.stage = 'solution-architecture' AND p.slug = '${projectSlug}' ORDER BY j.created_at DESC LIMIT 10` : `SELECT j.id, p.slug as project, j.stage, j.status, j.created_at, j.completed_at FROM architecture.jobs j JOIN architecture.projects p ON j.project_id = p.id WHERE j.stage = 'solution-architecture' ORDER BY j.created_at DESC LIMIT 10`;
    response.queryType = 'jobs';
    break;
  case 'artifacts':
    response.action = 'query_db';
    response.query = `SELECT a.id, p.slug as project, a.artifact_type, a.version, a.created_at FROM architecture.artifacts a JOIN architecture.projects p ON a.project_id = p.id WHERE a.artifact_type LIKE 'solution_%' ORDER BY a.created_at DESC LIMIT 10`;
    response.queryType = 'artifacts';
    break;
  case 'list':
    response.action = 'query_db';
    response.query = 'SELECT p.id, p.slug, p.name, p.created_at FROM architecture.projects p ORDER BY p.created_at DESC LIMIT 20';
    response.queryType = 'projects';
    break;
  default:
    response.content = 'Unknown command. Try help.';
    response.message = 'Unknown';
}
return [{ json: response }];

const chatContext = $('Chat Handler').first().json;
const queryResults = $input.all().map(i => i.json);
let content = '';
const queryType = chatContext.queryType;
if (queryResults.length === 0) { content = 'No results found.'; }
else {
  switch(queryType) {
    case 'jobs':
      content = '# Jobs\n\n| ID | Project | Stage | Status | Created | Completed |\n|----|---------|-------|--------|---------|-----------|\n';
      for (const row of queryResults) { content += `| ${row.id?.substring(0,8)}... | ${row.project} | ${row.stage} | ${row.status} | ${new Date(row.created_at).toLocaleDateString()} | ${row.completed_at ? new Date(row.completed_at).toLocaleDateString() : '-'} |\n`; }
      break;
    case 'artifacts':
      content = '# Artifacts\n\n| ID | Project | Type | Version | Created |\n|----|---------|------|---------|---------|\n';
      for (const row of queryResults) { content += `| ${row.id?.substring(0,8)}... | ${row.project} | ${row.artifact_type} | ${row.version} | ${new Date(row.created_at).toLocaleDateString()} |\n`; }
      break;
    case 'projects':
      content = '# Projects\n\n| Slug | Name | Created |\n|------|------|---------|\n';
      for (const row of queryResults) { content += `| ${row.slug} | ${row.name} | ${new Date(row.created_at).toLocaleDateString()} |\n`; }
      break;
    default: content = JSON.stringify(queryResults, null, 2);
  }
}
return [{ json: { agent: 'Solution Architect', stage: 'solution-architecture', intent: chatContext.intent, success: true, content: content, message: `Found ${queryResults.length} result(s)`, rowCount: queryResults.length } }];

const init = $('Initialize Parameters').first().json;
const project = $('Load Project').first().json;
const job = $json;
return [{ json: { ...init, projectId: project.id, projectSlug: project.slug, projectName: project.name || project.slug, jobId: job.id } }];

const ctx = $('Pass Context').first().json;
const rows = $input.all().map(i => i.json);
const byType = {};
for (const r of rows) byType[r.type] = r.content;
return [{ json: { ...ctx, artifacts: byType } }];

// Extract sequence diagrams from artifacts
const ctx = $json;

// Support both sequenceDiagrams and diagrams field names
const seqData = ctx.artifacts?.sequence_diagrams || {};
const sequenceDiagrams = seqData.sequenceDiagrams || seqData.diagrams || [];

if (!sequenceDiagrams.length) {
  return [{ json: { ...ctx, sequenceDiagrams: [], hasSequences: false } }];
}

const allParticipants = new Set();
for (const seq of sequenceDiagrams) {
  if (seq.mainFlow) {
    for (const step of seq.mainFlow) {
      if (step.from) allParticipants.add(step.from);
      if (step.to) allParticipants.add(step.to);
    }
  }
  if (seq.participants) {
    for (const p of seq.participants) {
      allParticipants.add(p);
    }
  }
}

return [{ json: { 
  ...ctx, 
  sequenceDiagrams, 
  participantsToResolve: Array.from(allParticipants),
  hasSequences: true 
} }];

// Prepare search queries with synonyms for better matching
const ctx = $json;
const participants = ctx.participantsToResolve || [];

if (!participants.length) {
  return [{ json: { ...ctx, componentSearchQueries: [] } }];
}

// Synonym mappings for common component names
const synonyms = {
  'Web App': ['frontend', 'web application', 'UI', 'client app', 'web frontend', 'react app', 'angular app'],
  'API Service': ['backend', 'REST API', 'API gateway', 'microservice', 'server', 'application server'],
  'Database': ['DB', 'postgres', 'postgresql', 'mysql', 'data store', 'persistence layer', 'repository'],
  'User': ['end user', 'customer', 'actor', 'client'],
  'System': ['scheduler', 'cron', 'background job', 'worker', 'automated process'],
  'Cache': ['redis', 'memcached', 'caching layer'],
  'Queue': ['message queue', 'rabbitmq', 'kafka', 'event bus']
};

const brd = ctx.artifacts?.brd || {};
const projectContext = brd.projectName || ctx.projectName || '';

const searchQueries = participants.map(p => {
  // Get synonyms for this participant
  const syns = synonyms[p] || [];
  const searchTerms = [p, ...syns].slice(0, 3).join(' ');

  return {
    participant: p,
    searchText: `${searchTerms} ${projectContext} component service`.slice(0, 250),
    synonyms: syns
  };
});

return [{ json: { ...ctx, componentSearchQueries: searchQueries } }];

// Search Qdrant and parse component info from markdown content
const ctx = $json;
const queries = ctx.componentSearchQueries || [];
const ollamaUrl = ctx.ollamaUrl || 'http://ollama:11434';
const qdrantUrl = ctx.qdrantUrl || 'http://qdrant:6333';

if (!queries.length) {
  return [{ json: { ...ctx, componentMatches: {} } }];
}

// Helper to extract component name from markdown content
function parseComponentFromContent(content, source) {
  // Try to extract name from # heading
  const headingMatch = content.match(/^#\s+(.+?)\n/m);
  const name = headingMatch ? headingMatch[1].trim() : null;

  // Try to extract from source filename
  const sourceMatch = source?.match(/([^/]+)\.md$/);
  const sourceName = sourceMatch ? sourceMatch[1].replace(/-/g, ' ').replace(/^sahatna /, '') : null;

  // Determine type from content
  let type = 'unknown';
  const lowerContent = content.toLowerCase();
  if (lowerContent.includes('service') || lowerContent.includes('api')) type = 'service';
  else if (lowerContent.includes('database') || lowerContent.includes('postgres')) type = 'database';
  else if (lowerContent.includes('frontend') || lowerContent.includes('web app')) type = 'frontend';
  else if (lowerContent.includes('worker') || lowerContent.includes('batch')) type = 'worker';
  else if (lowerContent.includes('queue') || lowerContent.includes('kafka')) type = 'queue';

  // Check if internal
  const isInternal = !lowerContent.includes('external');

  // Extract features/capabilities
  const features = [];
  const featuresMatch = content.match(/## (?:Main Features|Features|Capabilities)\n([\s\S]*?)(?=\n##|$)/i);
  if (featuresMatch) {
    const lines = featuresMatch[1].split('\n').filter(l => l.trim().startsWith('-'));
    features.push(...lines.map(l => l.replace(/^-\s*/, '').trim()).slice(0, 5));
  }

  return {
    component_name: name || sourceName || 'Unknown',
    component_type: type,
    is_internal: isInternal,
    capabilities: features,
    source: source
  };
}

const componentMatches = {};

for (const q of queries) {
  try {
    // Get embedding from Ollama
    const embResponse = await fetch(`${ollamaUrl}/api/embeddings`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ model: 'nomic-embed-text', prompt: q.searchText })
    });

    if (!embResponse.ok) {
      componentMatches[q.participant] = [];
      continue;
    }

    const embData = await embResponse.json();
    const embedding = embData.embedding;

    // Search Qdrant
    const searchResponse = await fetch(`${qdrantUrl}/collections/existing-landscape/points/search`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        vector: embedding,
        limit: 3,
        score_threshold: 0.4,
        with_payload: true
      })
    });

    if (!searchResponse.ok) {
      componentMatches[q.participant] = [];
      continue;
    }

    const searchData = await searchResponse.json();
    const results = (searchData.result || []).map(r => {
      const content = r.payload?.content || '';
      const source = r.payload?.metadata?.source || '';
      const parsed = parseComponentFromContent(content, source);
      return {
        score: r.score,
        payload: parsed
      };
    });

    if (results.length > 0) {
      console.log(`${q.participant}: Found ${results.length} matches, best: ${results[0].payload.component_name} (score: ${results[0].score.toFixed(3)})`);
    }

    componentMatches[q.participant] = results;

  } catch (e) {
    console.log(`Error searching for ${q.participant}: ${e.message}`);
    componentMatches[q.participant] = [];
  }
}

return [{ json: { ...ctx, componentMatches } }];

// Map sequence participants to concrete components
const ctx = $json;
const sequenceDiagrams = ctx.sequenceDiagrams || [];
const componentMatches = ctx.componentMatches || {};

if (!sequenceDiagrams.length) {
  return [{ json: { ...ctx, enrichedSequences: [] } }];
}

// Build participant resolution map
const participantMap = {};

for (const [participant, matches] of Object.entries(componentMatches)) {
  const bestMatch = matches[0]; // Highest score
  const score = bestMatch?.score || 0;
  const payload = bestMatch?.payload || {};

  participantMap[participant] = {
    abstract: participant,
    concrete: payload.component_name || participant,
    type: payload.component_type || 'unknown',
    isInternal: payload.is_internal !== false,
    exists: score > 0.65,
    score: score,
    port: payload.port || null,
    healthEndpoint: payload.health_endpoint || null,
    capabilities: payload.capabilities || [],
    integrations: payload.integrations || [],
    databaseSchema: payload.database_schema || null,
    tables: payload.tables || []
  };
}

// Enrich each sequence diagram
const enrichedSequences = sequenceDiagrams.map(seq => {
  // Classify participants
  const allParticipants = new Set();
  if (seq.mainFlow) {
    for (const step of seq.mainFlow) {
      if (step.from) allParticipants.add(step.from);
      if (step.to) allParticipants.add(step.to);
    }
  }

  const internal = [];
  const external = [];

  for (const p of allParticipants) {
    const resolved = participantMap[p] || { abstract: p, concrete: p, type: 'unknown', isInternal: true, exists: false };
    if (resolved.isInternal) {
      internal.push(resolved);
    } else {
      external.push(resolved);
    }
  }

  // Enrich flow steps
  const enrichedFlow = (seq.mainFlow || []).map((step, idx) => {
    const fromResolved = participantMap[step.from] || { abstract: step.from, concrete: step.from, type: 'unknown' };
    const toResolved = participantMap[step.to] || { abstract: step.to, concrete: step.to, type: 'unknown' };

    return {
      step: idx + 1,
      from: {
        component: fromResolved.concrete,
        type: fromResolved.type,
        exists: fromResolved.exists
      },
      to: {
        component: toResolved.concrete,
        type: toResolved.type,
        exists: toResolved.exists,
        endpoint: toResolved.healthEndpoint ? toResolved.healthEndpoint.replace('/actuator/health', '') : null
      },
      action: step.action,
      originalFrom: step.from,
      originalTo: step.to,
      // Placeholder for change assessment
      componentStatus: 'pending_assessment',
      ticket: null
    };
  });

  return {
    useCaseId: seq.useCaseId,
    useCaseName: seq.useCaseName,
    participants: { internal, external },
    enrichedFlow,
    originalFlow: seq.mainFlow,
    newComponentsRequired: []
  };
});

return [{ json: { ...ctx, enrichedSequences, participantMap } }];

