      "componentStatus": "exists" | "needs_change" | "new_required",
      "changeType": "api" | "database" | "integration" | "none",
      "ticket": { "title": "string", "type": "Story"|"Task", "priority": "High"|"Medium"|"Low" } | null
    }],
    "newComponentsRequired": [],
    "ticketSummary": { "totalTickets": number }
  }]
}

Be concise - focus on identifying changes, not detailed specs.' },
    { role: 'user', content: 'PROJECT: ' + $json.projectName + '

SEQUENCES TO ASSESS:
' + JSON.stringify($json.enrichedSequences).slice(0, 12000) }
  ],
  stream: false,
  format: { type: 'object', required: ['assessedSequences'], properties: { assessedSequences: { type: 'array', items: { type: 'object' } } } },
  options: { temperature: 0.1, seed: 42, num_ctx: 8192 }
} }}

parameters.jsCode:
// Parse LLM response and merge with enriched sequences
const ctx = $('Map Sequence to Components').first().json;
const llmResponse = $json;

let assessedSequences = ctx.enrichedSequences;

try {
  const content = llmResponse.message?.content;
  const parsed = typeof content === 'string' ? JSON.parse(content) : content;

  if (parsed?.assessedSequences) {
    assessedSequences = parsed.assessedSequences;
  }
} catch (e) {
  console.log('Failed to parse LLM assessment, using mapped sequences: ' + e.message);
}

// Calculate overall ticket summary
let totalTickets = 0;
const byPriority = { Critical: 0, High: 0, Medium: 0, Low: 0 };
const byType = { Story: 0, Task: 0, Bug: 0 };

for (const seq of assessedSequences) {
  if (seq.ticketSummary) {
    totalTickets += seq.ticketSummary.totalTickets || 0;
  }
  if (seq.enrichedFlow) {
    for (const step of seq.enrichedFlow) {
      if (step.ticket) {
        totalTickets++;
        if (step.ticket.priority) byPriority[step.ticket.priority] = (byPriority[step.ticket.priority] || 0) + 1;
        if (step.ticket.type) byType[step.ticket.type] = (byType[step.ticket.type] || 0) + 1;
      }
    }
  }
  if (seq.newComponentsRequired) {
    for (const nc of seq.newComponentsRequired) {
      if (nc.ticket) {
        totalTickets++;
        if (nc.ticket.priority) byPriority[nc.ticket.priority] = (byPriority[nc.ticket.priority] || 0) + 1;
        if (nc.ticket.type) byType[nc.ticket.type] = (byType[nc.ticket.type] || 0) + 1;
      }
    }
  }
}

const enrichedSequencesArtifact = {
  enrichedSequences: assessedSequences,
  overallSummary: {
    totalTickets,
    byPriority,
    byType,
    generatedAt: new Date().toISOString()
  }
};

return [{ json: { ...ctx, enrichedSequencesArtifact } }];

const raw = $json.message?.content;
let p; try { p = typeof raw === 'string' ? JSON.parse(raw) : raw; } catch (e) { return [{ json: { valid: false, error: 'JSON parse failed: ' + e.message } }]; }
const fnv1a = (s) => { let h = 0x811c9dc5; for (let i = 0; i < (s||'').length; i++) { h ^= s.charCodeAt(i); h = (h * 0x01000193) >>> 0; } return ('0000000' + h.toString(16)).slice(-8); };
const valid = p.solutionMarkdown && p.solutionMarkdown.startsWith('# Solution Architecture:');
return [{ json: {
  valid,
  integrationStyle: p.integrationStyle || 'rest_only',
  solutionMarkdown: p.solutionMarkdown || '',
  openapiYaml: p.openapiYaml || null,
  asyncapiYaml: p.asyncapiYaml || null,
  avroSchemasJson: p.avroSchemasJson || null,
  cloudEventsMarkdown: p.cloudEventsMarkdown || null,
  sqlSchemaSql: p.sqlSchemaSql || '',
  hashes: {
    solution: fnv1a(p.solutionMarkdown),
    openapi: fnv1a(p.openapiYaml),
    asyncapi: fnv1a(p.asyncapiYaml),
    avro: fnv1a(JSON.stringify(p.avroSchemasJson)),
    cloudEvents: fnv1a(p.cloudEventsMarkdown),
    sql: fnv1a(p.sqlSchemaSql)
  }
} }];

const j = $json;
if (!j.valid) return [];
const ctx = $('Pass Context').first().json;
const meta = { jobId: ctx.jobId, stage: 'solution-architecture', integrationStyle: j.integrationStyle };
const out = [];

// Always include solution architecture markdown
out.push({ json: { artifactType: 'solution_arch_md', content: { markdown: j.solutionMarkdown }, contentHash: j.hashes.solution, meta } });

// REST artifacts
if (j.openapiYaml) out.push({ json: { artifactType: 'openapi_yaml', content: { yaml: j.openapiYaml }, contentHash: j.hashes.openapi, meta } });

// Event-driven artifacts
if (j.asyncapiYaml) out.push({ json: { artifactType: 'asyncapi_yaml', content: { yaml: j.asyncapiYaml }, contentHash: j.hashes.asyncapi, meta } });
if (j.avroSchemasJson) out.push({ json: { artifactType: 'avro_schemas_json', content: { schemas: j.avroSchemasJson }, contentHash: j.hashes.avro, meta } });
if (j.cloudEventsMarkdown) out.push({ json: { artifactType: 'cloud_events_md', content: { markdown: j.cloudEventsMarkdown }, contentHash: j.hashes.cloudEvents, meta } });

// Database artifacts
if (j.sqlSchemaSql) out.push({ json: { artifactType: 'sql_schema_sql', content: { sql: j.sqlSchemaSql }, contentHash: j.hashes.sql, meta } });

return out;

const ctx = $('Pass Context').first().json;
const sol = $('Validate Solution').first().json;
const enrichedSeq = $('Merge Change Assessment').first().json.enrichedSequencesArtifact || {};
const projectSlug = ctx.projectSlug;
const jobId = ctx.jobId;
const repoDir = '/opt/workspace/software-delivery';
const projectDir = repoDir + '/' + projectSlug + '-docs';
const remote = 'git@github.com:shlapolosa/software-delivery.git';

// Helper to safely escape heredoc content
const safeHeredoc = (content, marker) => {
  if (!content) return '';
  return String(content).replace(new RegExp(marker, 'g'), marker + '_ESCAPED');
};

let sh = `set -e
mkdir -p /opt/workspace

if [ ! -d '${repoDir}/.git' ]; then
  git clone '${remote}' '${repoDir}'
fi
cd '${repoDir}'
git fetch origin --prune

git checkout -B '${projectSlug}' 'origin/${projectSlug}' 2>/dev/null || git checkout -B '${projectSlug}'
mkdir -p '${projectDir}/docs' '${projectDir}/api' '${projectDir}/db'
`;

// Solution Architecture markdown
sh += `cat > '${projectDir}/docs/solution-architecture.md' <<'EOFSOL_${jobId}'
${safeHeredoc(sol.solutionMarkdown, 'EOFSOL_' + jobId)}
EOFSOL_${jobId}
`;

// Enriched Sequences JSON
if (enrichedSeq.enrichedSequences) {
  sh += `cat > '${projectDir}/docs/enriched-sequences.json' <<'EOFSEQ_${jobId}'
${safeHeredoc(JSON.stringify(enrichedSeq, null, 2), 'EOFSEQ_' + jobId)}
EOFSEQ_${jobId}
`;
}

// REST API spec
if (sol.openapiYaml) {
  sh += `cat > '${projectDir}/api/openapi.yaml' <<'EOFAPI_${jobId}'
${safeHeredoc(sol.openapiYaml, 'EOFAPI_' + jobId)}
EOFAPI_${jobId}
`;
}

// Event-driven specs
if (sol.asyncapiYaml) {
  sh += `cat > '${projectDir}/api/asyncapi.yaml' <<'EOFASYNC_${jobId}'
${safeHeredoc(sol.asyncapiYaml, 'EOFASYNC_' + jobId)}
EOFASYNC_${jobId}
`;
}

if (sol.avroSchemasJson) {
  sh += `cat > '${projectDir}/api/avro-schemas.json' <<'EOFAVRO_${jobId}'
${safeHeredoc(JSON.stringify(sol.avroSchemasJson, null, 2), 'EOFAVRO_' + jobId)}
EOFAVRO_${jobId}
`;
}

if (sol.cloudEventsMarkdown) {
  sh += `cat > '${projectDir}/docs/cloud-events.md' <<'EOFCE_${jobId}'
${safeHeredoc(sol.cloudEventsMarkdown, 'EOFCE_' + jobId)}
EOFCE_${jobId}
`;
}

// Database schema
if (sol.sqlSchemaSql) {
  sh += `cat > '${projectDir}/db/schema.sql' <<'EOFSQL_${jobId}'
${safeHeredoc(sol.sqlSchemaSql, 'EOFSQL_' + jobId)}
EOFSQL_${jobId}
`;
}

sh += `
git add '${projectSlug}-docs'
git commit -m 'Add solution architecture for ${projectSlug} (job ${jobId})' || true
git push -u origin '${projectSlug}'
`;

return [{ json: { ...ctx, integrationStyle: sol.integrationStyle, enrichedSequences: enrichedSeq, gitScript: sh } }];

// Build Azure DevOps push payload
const ctx = $("Build Git Script").first().json;
const repoInfo = $("Get Azure Repo Info").first().json;
const branchCheck = $("Check Azure Branch").first().json;
const fileCheck = $json;
const projectSlug = ctx.projectSlug;
const jobId = ctx.jobId;

const artifactContent = ctx.artifactContent || ctx.artifactMarkdown || ctx.content || "";
const artifactPath = "/docs/solution-architecture.md";
const branchName = `refs/heads/${projectSlug}`;

let oldObjectId = "0000000000000000000000000000000000000000";
let changeType = "add";

// Check if branch exists
if (branchCheck.value && branchCheck.value.length > 0) {
  oldObjectId = branchCheck.value[0].objectId;
}

// Check if file exists (statusCode 200 = exists, 404 = doesn't exist)
const fileExists = fileCheck.statusCode === 200;
if (fileExists) {
  changeType = "edit";
} else {
  changeType = "add";
}

const changes = [{
  changeType: changeType,
  item: { path: `/${projectSlug}-docs${artifactPath}` },
  newContent: {
    content: Buffer.from(artifactContent).toString("base64"),
    contentType: "base64encoded"
  }
}];

return [{
  json: {
    ...ctx,
    azurePushPayload: {
      refUpdates: [{ name: branchName, oldObjectId: oldObjectId }],
      commits: [{ comment: `Add solution architecture for ${projectSlug} (job ${jobId})`, changes: changes }]
    },
    azureRepoInfo: repoInfo,
    branchExists: branchCheck.value && branchCheck.value.length > 0,
    fileExists: fileExists,
    changeType: changeType
  }
}];

const ctx = $('Pass Context').first().json;
const sol = $('Validate Solution').first().json;
const enrichedSeq = $('Merge Change Assessment').first().json.enrichedSequencesArtifact || {};
return [{ json: {
  success: true,
  jobId: ctx.jobId,
  projectSlug: ctx.projectSlug,
  stage: 'solution-architecture',
  integrationStyle: sol.integrationStyle,
  enrichedSequences: {
    totalTickets: enrichedSeq.overallSummary?.totalTickets || 0,
    byPriority: enrichedSeq.overallSummary?.byPriority || {},
    byType: enrichedSeq.overallSummary?.byType || {}
  },
  artifacts: {
    solutionArch: ctx.projectSlug + '-docs/docs/solution-architecture.md',
    enrichedSequences: ctx.projectSlug + '-docs/docs/enriched-sequences.json',
    openapi: sol.openapiYaml ? ctx.projectSlug + '-docs/api/openapi.yaml' : null,
    asyncapi: sol.asyncapiYaml ? ctx.projectSlug + '-docs/api/asyncapi.yaml' : null,
    avroSchemas: sol.avroSchemasJson ? ctx.projectSlug + '-docs/api/avro-schemas.json' : null,
    cloudEvents: sol.cloudEventsMarkdown ? ctx.projectSlug + '-docs/docs/cloud-events.md' : null,
    sqlSchema: sol.sqlSchemaSql ? ctx.projectSlug + '-docs/db/schema.sql' : null
  }
} }];

const ctx = $json;
const sequences = ctx.enrichedSequencesArtifact?.enrichedSequences || [];
const internalComponents = new Set(["User", "Admin", "System", "Web App", "API Service", "Database", "Cache", "Frontend", "Backend", "Queue", "Worker"]);
const externalIntegrations = new Set();
const asyncOperations = [];
const integrationEndpoints = [];

for (const seq of sequences) {
  const participants = [...(seq.participants?.internal || []), ...(seq.participants?.external || [])];
  for (const p of participants) {
    const name = p.abstract || p.name || p;
    if (!internalComponents.has(name) && typeof name === "string") {
      const lowerName = name.toLowerCase();
      if (lowerName.includes("service") || lowerName.includes("system") || lowerName.includes("api") || lowerName.includes("provider") || lowerName.includes("external")) {
        externalIntegrations.add(name);
      }
    }
  }
  const ucName = (seq.useCaseName || "").toLowerCase();
  if (ucName.includes("remind") || ucName.includes("notification") || ucName.includes("alert") || ucName.includes("schedule") || ucName.includes("batch") || ucName.includes("async")) {
    asyncOperations.push(seq.useCaseName);
  }
  for (const step of seq.enrichedFlow || []) {
    const fromComp = step.from?.component || "";
    const toComp = step.to?.component || "";
    const action = step.action || step.description || "";
    if (action && (fromComp || toComp)) {
      integrationEndpoints.push({ from: fromComp, to: toComp, action: action, sequence: seq.useCaseName });
    }
    if (fromComp === "System" || toComp === "System") {
      const asyncOp = seq.useCaseName + ": " + action;
      if (!asyncOperations.includes(asyncOp)) { asyncOperations.push(asyncOp); }
    }
    if (!internalComponents.has(fromComp) && fromComp) { externalIntegrations.add(fromComp); }
    if (!internalComponents.has(toComp) && toComp) { externalIntegrations.add(toComp); }
  }
}

const integrationAnalysis = {
  externalIntegrations: Array.from(externalIntegrations),
  asyncOperations: [...new Set(asyncOperations)],
  integrationEndpoints: integrationEndpoints.slice(0, 50),
  summary: { externalSystemCount: externalIntegrations.size, asyncOperationCount: asyncOperations.length, totalEndpointsIdentified: integrationEndpoints.length, sequenceCount: sequences.length, totalSteps: sequences.reduce((sum, s) => sum + (s.enrichedFlow?.length || 0), 0) }
};

console.log("Integration Analysis:", JSON.stringify(integrationAnalysis.summary, null, 2));

return [{ json: { ...ctx, integrationAnalysis } }];

// Parse and normalize incoming request
// Detect Open WebUI system prompts (auto-tagging, follow-ups, title generation)
const input = $json.body || $json;

// Check multiple possible field names for user input
// Open WebUI may send as chatInput, projectSlug, message, or query
const chatInput = input.chatInput || input.message || input.query || input.projectSlug || '';
const requirements = input.requirements || '';

// Detect Open WebUI system prompts
const isAutoTag = chatInput.includes('### Task:') && chatInput.includes('Generate 1-3 broad tags');
const isFollowUp = chatInput.includes('### Task:') && chatInput.includes('Suggest 3-5 relevant follow-up');
const isTitleGen = chatInput.includes('### Task:') && chatInput.includes('Generate a concise');
const isSystemPrompt = isAutoTag || isFollowUp || isTitleGen;

// Also check requirements field for system prompts
const reqIsAutoTag = requirements.includes('### Task:') && requirements.includes('Generate 1-3 broad tags');
const reqIsFollowUp = requirements.includes('### Task:') && requirements.includes('Suggest 3-5 relevant follow-up');
const reqIsTitleGen = requirements.includes('### Task:') && requirements.includes('Generate a concise');
const reqIsSystemPrompt = reqIsAutoTag || reqIsFollowUp || reqIsTitleGen;

// Determine system prompt type
let systemPromptType = null;
if (isAutoTag || reqIsAutoTag) systemPromptType = 'auto-tag';
else if (isFollowUp || reqIsFollowUp) systemPromptType = 'follow-up';
else if (isTitleGen || reqIsTitleGen) systemPromptType = 'title-gen';

// Only use projectSlug from input if it looks like a slug (no spaces, short)
// Otherwise it might be the user message sent with wrong field name
const inputProjectSlug = input.projectSlug || null;
const looksLikeSlug = inputProjectSlug && inputProjectSlug.length < 100 && !inputProjectSlug.includes(' ');
const actualProjectSlug = looksLikeSlug ? inputProjectSlug : null;

// FIX: Use requirements as fallback for rawInput when not a system prompt
// This handles Open WebUI sending user messages in the requirements field
let rawInput = chatInput;
if (!rawInput && !(isSystemPrompt || reqIsSystemPrompt) && requirements) {
  rawInput = requirements;
}

return [{ json: {
  rawInput: rawInput,
  projectSlug: actualProjectSlug,
  projectName: input.projectName || null,
  requirements: input.requirements || null,
  sessionId: input.sessionId || null,
  isSystemPrompt: isSystemPrompt || reqIsSystemPrompt,
  systemPromptType: systemPromptType
} }];

const type = $input.first().json.systemPromptType;
let response = {};
if (type === 'auto-tag') { response = { tags: ['solution-architecture', 'architecture'] }; }
else if (type === 'follow-up') { response = { questions: ['What specific aspects would you like to explore?'] }; }
else if (type === 'title-gen') { response = { title: 'Solution Architect Assistant' }; }
return [{ json: response }];

parameters.jsonBody:
={{ {
  model: 'qwen2.5:7b-instruct-q4_K_M',
  messages: [
    {
      role: 'system',
      content: 'You are a classifier for a Solution Architecture pipeline. Analyze the user input and determine the mode, intent, and extract project information.\n\nMODE RULES:\n- mode=chat: For queries, help requests, status checks. Keywords: help, status, list, artifacts, jobs, what, how, show, get, query, ?\n- mode=execute: For creating/building/generating solution architecture. Keywords: build, create, generate, make, develop, design a, implement\n\nIf input is a single word like \"help\", \"list\", \"jobs\", \"status\" - it is ALWAYS mode=chat.\nIf input asks a question or requests information - it is mode=chat.\nOnly use mode=execute when user explicitly wants to CREATE or BUILD something new.\n\nIMPORTANT: If the input looks like a project slug (short string, no spaces), check the requirements field for actual intent.\n\nPROJECT EXTRACTION:\n- Extract the project slug/name if mentioned (e.g., \"project healthcare-scheduler\" -> projectSlug: \"healthcare-scheduler\")\n- Look for patterns like: \"project X\", \"for X\", \"X project\"\n\nChat intents: help, status, artifacts, jobs, list\nExecute intents: create, build, generate\n\nOutput JSON only.'
    },
    { role: 'user', content: (($json.rawInput || '') + ' ' + ($json.requirements || '')).trim() || 'help' }
  ],
  stream: false,
  format: {
    type: 'object',
    required: ['mode', 'intent'],
    properties: {
      mode: { type: 'string', enum: ['chat', 'execute'] },
      intent: { type: 'string' },
      projectSlug: { type: 'string' },
      requirements: { type: 'string' }
    }
  },
  options: { temperature: 0.1 }
} }}

parameters.jsCode:
const response = $input.first().json;
const parsed = $('Parse Input').first().json;
let classification = { mode: 'chat', intent: 'help' };
try { const content = response.message?.content; if (content) classification = JSON.parse(content); } catch (e) {}
return [{ json: { ...parsed, mode: classification.mode || 'chat', intent: classification.intent || 'help', extractedProjectSlug: classification.projectSlug || null } }];

const input = $input.first().json;
const intent = input.intent || 'help';
const projectSlug = input.projectSlug || input.extractedProjectSlug;
let response = { agent: 'Solution Architect', stage: 'solution-architecture', intent: intent, action: 'direct_response', query: null };
switch(intent) {
  case 'help':
    response.content = '# Solution Architecture Pipeline\n\n## Commands\n| Command | Description |\n|---------|-------------|\n| help | Show help |\n| status | Check job status |\n| artifacts | List artifacts |\n| jobs | List recent jobs |\n| list | List projects |';
    response.message = 'Help';
    break;
  case 'status': case 'jobs':
    response.action = 'query_db';
    response.query = projectSlug ? `SELECT j.id, p.slug as project, j.stage, j.status, j.created_at, j.completed_at FROM architecture.jobs j JOIN architecture.projects p ON j.project_id = p.id WHERE j.stage = 'solution-architecture' AND p.slug = '${projectSlug}' ORDER BY j.created_at DESC LIMIT 10` : `SELECT j.id, p.slug as project, j.stage, j.status, j.created_at, j.completed_at FROM architecture.jobs j JOIN architecture.projects p ON j.project_id = p.id WHERE j.stage = 'solution-architecture' ORDER BY j.created_at DESC LIMIT 10`;
    response.queryType = 'jobs';
    break;
  case 'artifacts':
    response.action = 'query_db';
    response.query = `SELECT a.id, p.slug as project, a.artifact_type, a.version, a.created_at FROM architecture.artifacts a JOIN architecture.projects p ON a.project_id = p.id WHERE a.artifact_type LIKE 'solution_%' ORDER BY a.created_at DESC LIMIT 10`;
    response.queryType = 'artifacts';
    break;
  case 'list':
    response.action = 'query_db';
    response.query = 'SELECT p.id, p.slug, p.name, p.created_at FROM architecture.projects p ORDER BY p.created_at DESC LIMIT 20';
    response.queryType = 'projects';
    break;
  default:
    response.content = 'Unknown command. Try help.';
    response.message = 'Unknown';
}
return [{ json: response }];

const chatContext = $('Chat Handler').first().json;
const queryResults = $input.all().map(i => i.json);
let content = '';
const queryType = chatContext.queryType;
if (queryResults.length === 0) { content = 'No results found.'; }
else {
  switch(queryType) {
    case 'jobs':
      content = '# Jobs\n\n| ID | Project | Stage | Status | Created | Completed |\n|----|---------|-------|--------|---------|-----------|\n';
      for (const row of queryResults) { content += `| ${row.id?.substring(0,8)}... | ${row.project} | ${row.stage} | ${row.status} | ${new Date(row.created_at).toLocaleDateString()} | ${row.completed_at ? new Date(row.completed_at).toLocaleDateString() : '-'} |\n`; }
      break;
    case 'artifacts':
      content = '# Artifacts\n\n| ID | Project | Type | Version | Created |\n|----|---------|------|---------|---------|\n';
      for (const row of queryResults) { content += `| ${row.id?.substring(0,8)}... | ${row.project} | ${row.artifact_type} | ${row.version} | ${new Date(row.created_at).toLocaleDateString()} |\n`; }
      break;
    case 'projects':
      content = '# Projects\n\n| Slug | Name | Created |\n|------|------|---------|\n';
      for (const row of queryResults) { content += `| ${row.slug} | ${row.name} | ${new Date(row.created_at).toLocaleDateString()} |\n`; }
      break;
    default: content = JSON.stringify(queryResults, null, 2);
  }
}
return [{ json: { agent: 'Solution Architect', stage: 'solution-architecture', intent: chatContext.intent, success: true, content: content, message: `Found ${queryResults.length} result(s)`, rowCount: queryResults.length } }];

const init = $('Initialize Parameters').first().json;
const project = $('Load Project').first().json;
const job = $json;
return [{ json: { ...init, projectId: project.id, projectSlug: project.slug, projectName: project.name || project.slug, jobId: job.id } }];

const ctx = $('Pass Context').first().json;
const rows = $input.all().map(i => i.json);
const byType = {};
for (const r of rows) byType[r.type] = r.content;
return [{ json: { ...ctx, artifacts: byType } }];

// Extract sequence diagrams from artifacts
const ctx = $json;

// Support both sequenceDiagrams and diagrams field names
const seqData = ctx.artifacts?.sequence_diagrams || {};
const sequenceDiagrams = seqData.sequenceDiagrams || seqData.diagrams || [];

if (!sequenceDiagrams.length) {
  return [{ json: { ...ctx, sequenceDiagrams: [], hasSequences: false } }];
}

const allParticipants = new Set();
for (const seq of sequenceDiagrams) {
  if (seq.mainFlow) {
    for (const step of seq.mainFlow) {
      if (step.from) allParticipants.add(step.from);
      if (step.to) allParticipants.add(step.to);
    }
  }
  if (seq.participants) {
    for (const p of seq.participants) {
      allParticipants.add(p);
    }
  }
}

return [{ json: { 
  ...ctx, 
  sequenceDiagrams, 
  participantsToResolve: Array.from(allParticipants),
  hasSequences: true 
} }];

// Prepare search queries with synonyms for better matching
const ctx = $json;
const participants = ctx.participantsToResolve || [];

if (!participants.length) {
  return [{ json: { ...ctx, componentSearchQueries: [] } }];
}

// Synonym mappings for common component names
const synonyms = {
  'Web App': ['frontend', 'web application', 'UI', 'client app', 'web frontend', 'react app', 'angular app'],
  'API Service': ['backend', 'REST API', 'API gateway', 'microservice', 'server', 'application server'],
  'Database': ['DB', 'postgres', 'postgresql', 'mysql', 'data store', 'persistence layer', 'repository'],
  'User': ['end user', 'customer', 'actor', 'client'],
  'System': ['scheduler', 'cron', 'background job', 'worker', 'automated process'],
  'Cache': ['redis', 'memcached', 'caching layer'],
  'Queue': ['message queue', 'rabbitmq', 'kafka', 'event bus']
};

const brd = ctx.artifacts?.brd || {};
const projectContext = brd.projectName || ctx.projectName || '';

const searchQueries = participants.map(p => {
  // Get synonyms for this participant
  const syns = synonyms[p] || [];
  const searchTerms = [p, ...syns].slice(0, 3).join(' ');

  return {
    participant: p,
    searchText: `${searchTerms} ${projectContext} component service`.slice(0, 250),
    synonyms: syns
  };
});

return [{ json: { ...ctx, componentSearchQueries: searchQueries } }];

// Search Qdrant and parse component info from markdown content
const ctx = $json;
const queries = ctx.componentSearchQueries || [];
const ollamaUrl = ctx.ollamaUrl || 'http://ollama:11434';
const qdrantUrl = ctx.qdrantUrl || 'http://qdrant:6333';

if (!queries.length) {
  return [{ json: { ...ctx, componentMatches: {} } }];
}

// Helper to extract component name from markdown content
function parseComponentFromContent(content, source) {
  // Try to extract name from # heading
  const headingMatch = content.match(/^#\s+(.+?)\n/m);
  const name = headingMatch ? headingMatch[1].trim() : null;

  // Try to extract from source filename
  const sourceMatch = source?.match(/([^/]+)\.md$/);
  const sourceName = sourceMatch ? sourceMatch[1].replace(/-/g, ' ').replace(/^sahatna /, '') : null;

  // Determine type from content
  let type = 'unknown';
  const lowerContent = content.toLowerCase();
  if (lowerContent.includes('service') || lowerContent.includes('api')) type = 'service';
  else if (lowerContent.includes('database') || lowerContent.includes('postgres')) type = 'database';
  else if (lowerContent.includes('frontend') || lowerContent.includes('web app')) type = 'frontend';
  else if (lowerContent.includes('worker') || lowerContent.includes('batch')) type = 'worker';
  else if (lowerContent.includes('queue') || lowerContent.includes('kafka')) type = 'queue';

  // Check if internal
  const isInternal = !lowerContent.includes('external');

  // Extract features/capabilities
  const features = [];
  const featuresMatch = content.match(/## (?:Main Features|Features|Capabilities)\n([\s\S]*?)(?=\n##|$)/i);
  if (featuresMatch) {
    const lines = featuresMatch[1].split('\n').filter(l => l.trim().startsWith('-'));
    features.push(...lines.map(l => l.replace(/^-\s*/, '').trim()).slice(0, 5));
  }

  return {
    component_name: name || sourceName || 'Unknown',
    component_type: type,
    is_internal: isInternal,
    capabilities: features,
    source: source
  };
}

const componentMatches = {};

for (const q of queries) {
  try {
    // Get embedding from Ollama
    const embResponse = await fetch(`${ollamaUrl}/api/embeddings`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ model: 'nomic-embed-text', prompt: q.searchText })
    });

    if (!embResponse.ok) {
      componentMatches[q.participant] = [];
      continue;
    }

    const embData = await embResponse.json();
    const embedding = embData.embedding;

    // Search Qdrant
    const searchResponse = await fetch(`${qdrantUrl}/collections/existing-landscape/points/search`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        vector: embedding,
        limit: 3,
        score_threshold: 0.4,
        with_payload: true
      })
    });

    if (!searchResponse.ok) {
      componentMatches[q.participant] = [];
      continue;
    }

    const searchData = await searchResponse.json();
    const results = (searchData.result || []).map(r => {
      const content = r.payload?.content || '';
      const source = r.payload?.metadata?.source || '';
      const parsed = parseComponentFromContent(content, source);
      return {
        score: r.score,
        payload: parsed
      };
    });

    if (results.length > 0) {
      console.log(`${q.participant}: Found ${results.length} matches, best: ${results[0].payload.component_name} (score: ${results[0].score.toFixed(3)})`);
    }

    componentMatches[q.participant] = results;

  } catch (e) {
    console.log(`Error searching for ${q.participant}: ${e.message}`);
    componentMatches[q.participant] = [];
  }
}

return [{ json: { ...ctx, componentMatches } }];

// Map sequence participants to concrete components
const ctx = $json;
const sequenceDiagrams = ctx.sequenceDiagrams || [];
const componentMatches = ctx.componentMatches || {};

if (!sequenceDiagrams.length) {
  return [{ json: { ...ctx, enrichedSequences: [] } }];
}

// Build participant resolution map
const participantMap = {};

for (const [participant, matches] of Object.entries(componentMatches)) {
  const bestMatch = matches[0]; // Highest score
  const score = bestMatch?.score || 0;
  const payload = bestMatch?.payload || {};

  participantMap[participant] = {
    abstract: participant,
    concrete: payload.component_name || participant,
    type: payload.component_type || 'unknown',
    isInternal: payload.is_internal !== false,
    exists: score > 0.65,
    score: score,
    port: payload.port || null,
    healthEndpoint: payload.health_endpoint || null,
    capabilities: payload.capabilities || [],
    integrations: payload.integrations || [],
    databaseSchema: payload.database_schema || null,
    tables: payload.tables || []
  };
}

// Enrich each sequence diagram
const enrichedSequences = sequenceDiagrams.map(seq => {
  // Classify participants
  const allParticipants = new Set();
  if (seq.mainFlow) {
    for (const step of seq.mainFlow) {
      if (step.from) allParticipants.add(step.from);
      if (step.to) allParticipants.add(step.to);
    }
  }

  const internal = [];
  const external = [];

  for (const p of allParticipants) {
    const resolved = participantMap[p] || { abstract: p, concrete: p, type: 'unknown', isInternal: true, exists: false };
    if (resolved.isInternal) {
      internal.push(resolved);
    } else {
      external.push(resolved);
    }
  }

  // Enrich flow steps
  const enrichedFlow = (seq.mainFlow || []).map((step, idx) => {
    const fromResolved = participantMap[step.from] || { abstract: step.from, concrete: step.from, type: 'unknown' };
    const toResolved = participantMap[step.to] || { abstract: step.to, concrete: step.to, type: 'unknown' };

    return {
      step: idx + 1,
      from: {
        component: fromResolved.concrete,
        type: fromResolved.type,
        exists: fromResolved.exists
      },
      to: {
        component: toResolved.concrete,
        type: toResolved.type,
        exists: toResolved.exists,
        endpoint: toResolved.healthEndpoint ? toResolved.healthEndpoint.replace('/actuator/health', '') : null
      },
      action: step.action,
      originalFrom: step.from,
      originalTo: step.to,
      // Placeholder for change assessment
      componentStatus: 'pending_assessment',
      ticket: null
    };
  });

  return {
    useCaseId: seq.useCaseId,
    useCaseName: seq.useCaseName,
    participants: { internal, external },
    enrichedFlow,
    originalFlow: seq.mainFlow,
    newComponentsRequired: []
  };
});

return [{ json: { ...ctx, enrichedSequences, participantMap } }];

parameters.jsonBody:
={{ {
  model: $('Initialize Parameters').first().json.assessmentModel || $('Initialize Parameters').first().json.ollamaModel,
  messages: [
    { role: 'system', content: 'You are a solution architect assessing component changes for sequence diagrams.

For each sequence, identify:
1. Which steps need new/changed components
2. Basic ticket info for changes

Output JSON:
{
  "assessedSequences": [{
    "useCaseId": "string",
    "useCaseName": "string",
    "enrichedFlow": [{
      "step": number,
      "from": { "component": "string", "type": "string" },
      "to": { "component": "string", "type": "string" },
      "action": "string",
      "componentStatus": "exists" | "needs_change" | "new_required",
      "changeType": "api" | "database" | "integration" | "none",
      "ticket": { "title": "string", "type": "Story"|"Task", "priority": "High"|"Medium"|"Low" } | null
    }],
    "newComponentsRequired": [],
    "ticketSummary": { "totalTickets": number }
  }]
}

Be concise - focus on identifying changes, not detailed specs.' },
    { role: 'user', content: 'PROJECT: ' + $json.projectName + '

SEQUENCES TO ASSESS:
' + JSON.stringify($json.enrichedSequences).slice(0, 12000) }
  ],
  stream: false,
  format: { type: 'object', required: ['assessedSequences'], properties: { assessedSequences: { type: 'array', items: { type: 'object' } } } },
