// Parse LLM response and merge with enriched sequences
const ctx = $('Map Sequence to Components').first().json;
const llmResponse = $json;

let assessedSequences = ctx.enrichedSequences;

try {
  const content = llmResponse.message?.content;
  const parsed = typeof content === 'string' ? JSON.parse(content) : content;

  if (parsed?.assessedSequences) {
    assessedSequences = parsed.assessedSequences;
  }
} catch (e) {
  console.log('Failed to parse LLM assessment, using mapped sequences: ' + e.message);
}

// Calculate overall ticket summary
let totalTickets = 0;
const byPriority = { Critical: 0, High: 0, Medium: 0, Low: 0 };
const byType = { Story: 0, Task: 0, Bug: 0 };

for (const seq of assessedSequences) {
  if (seq.ticketSummary) {
    totalTickets += seq.ticketSummary.totalTickets || 0;
  }
  if (seq.enrichedFlow) {
    for (const step of seq.enrichedFlow) {
      if (step.ticket) {
        totalTickets++;
        if (step.ticket.priority) byPriority[step.ticket.priority] = (byPriority[step.ticket.priority] || 0) + 1;
        if (step.ticket.type) byType[step.ticket.type] = (byType[step.ticket.type] || 0) + 1;
      }
    }
  }
  if (seq.newComponentsRequired) {
    for (const nc of seq.newComponentsRequired) {
      if (nc.ticket) {
        totalTickets++;
        if (nc.ticket.priority) byPriority[nc.ticket.priority] = (byPriority[nc.ticket.priority] || 0) + 1;
        if (nc.ticket.type) byType[nc.ticket.type] = (byType[nc.ticket.type] || 0) + 1;
      }
    }
  }
}

const enrichedSequencesArtifact = {
  enrichedSequences: assessedSequences,
  overallSummary: {
    totalTickets,
    byPriority,
    byType,
    generatedAt: new Date().toISOString()
  }
};

return [{ json: { ...ctx, enrichedSequencesArtifact } }];

const raw = $json.message?.content;
let p; try { p = typeof raw === 'string' ? JSON.parse(raw) : raw; } catch (e) { return [{ json: { valid: false, error: 'JSON parse failed: ' + e.message } }]; }
const fnv1a = (s) => { let h = 0x811c9dc5; for (let i = 0; i < (s||'').length; i++) { h ^= s.charCodeAt(i); h = (h * 0x01000193) >>> 0; } return ('0000000' + h.toString(16)).slice(-8); };
const valid = p.solutionMarkdown && p.solutionMarkdown.startsWith('# Solution Architecture:');
return [{ json: {
  valid,
  integrationStyle: p.integrationStyle || 'rest_only',
  solutionMarkdown: p.solutionMarkdown || '',
  openapiYaml: p.openapiYaml || null,
  asyncapiYaml: p.asyncapiYaml || null,
  avroSchemasJson: p.avroSchemasJson || null,
  cloudEventsMarkdown: p.cloudEventsMarkdown || null,
  sqlSchemaSql: p.sqlSchemaSql || '',
  hashes: {
    solution: fnv1a(p.solutionMarkdown),
    openapi: fnv1a(p.openapiYaml),
    asyncapi: fnv1a(p.asyncapiYaml),
    avro: fnv1a(JSON.stringify(p.avroSchemasJson)),
    cloudEvents: fnv1a(p.cloudEventsMarkdown),
    sql: fnv1a(p.sqlSchemaSql)
  }
} }];

const j = $json;
if (!j.valid) return [];
const ctx = $('Pass Context').first().json;
const meta = { jobId: ctx.jobId, stage: 'solution-architecture', integrationStyle: j.integrationStyle };
const out = [];

// Always include solution architecture markdown
out.push({ json: { artifactType: 'solution_arch_md', content: { markdown: j.solutionMarkdown }, contentHash: j.hashes.solution, meta } });

// REST artifacts
if (j.openapiYaml) out.push({ json: { artifactType: 'openapi_yaml', content: { yaml: j.openapiYaml }, contentHash: j.hashes.openapi, meta } });

// Event-driven artifacts
if (j.asyncapiYaml) out.push({ json: { artifactType: 'asyncapi_yaml', content: { yaml: j.asyncapiYaml }, contentHash: j.hashes.asyncapi, meta } });
if (j.avroSchemasJson) out.push({ json: { artifactType: 'avro_schemas_json', content: { schemas: j.avroSchemasJson }, contentHash: j.hashes.avro, meta } });
if (j.cloudEventsMarkdown) out.push({ json: { artifactType: 'cloud_events_md', content: { markdown: j.cloudEventsMarkdown }, contentHash: j.hashes.cloudEvents, meta } });

// Database artifacts
if (j.sqlSchemaSql) out.push({ json: { artifactType: 'sql_schema_sql', content: { sql: j.sqlSchemaSql }, contentHash: j.hashes.sql, meta } });

return out;

const ctx = $('Pass Context').first().json;
const sol = $('Validate Solution').first().json;
const enrichedSeq = $('Merge Change Assessment').first().json.enrichedSequencesArtifact || {};
const projectSlug = ctx.projectSlug;
const jobId = ctx.jobId;
const repoDir = '/opt/workspace/software-delivery';
const projectDir = repoDir + '/' + projectSlug + '-docs';
const remote = 'git@github.com:shlapolosa/software-delivery.git';

// Helper to safely escape heredoc content
const safeHeredoc = (content, marker) => {
  if (!content) return '';
  return String(content).replace(new RegExp(marker, 'g'), marker + '_ESCAPED');
};

let sh = `set -e
mkdir -p /opt/workspace

if [ ! -d '${repoDir}/.git' ]; then
  git clone '${remote}' '${repoDir}'
fi
cd '${repoDir}'
git fetch origin --prune

git checkout -B '${projectSlug}' 'origin/${projectSlug}' 2>/dev/null || git checkout -B '${projectSlug}'
mkdir -p '${projectDir}/docs' '${projectDir}/api' '${projectDir}/db'
`;

// Solution Architecture markdown
sh += `cat > '${projectDir}/docs/solution-architecture.md' <<'EOFSOL_${jobId}'
${safeHeredoc(sol.solutionMarkdown, 'EOFSOL_' + jobId)}
EOFSOL_${jobId}
`;

// Enriched Sequences JSON
if (enrichedSeq.enrichedSequences) {
  sh += `cat > '${projectDir}/docs/enriched-sequences.json' <<'EOFSEQ_${jobId}'
${safeHeredoc(JSON.stringify(enrichedSeq, null, 2), 'EOFSEQ_' + jobId)}
EOFSEQ_${jobId}
`;
}

// REST API spec
if (sol.openapiYaml) {
  sh += `cat > '${projectDir}/api/openapi.yaml' <<'EOFAPI_${jobId}'
${safeHeredoc(sol.openapiYaml, 'EOFAPI_' + jobId)}
EOFAPI_${jobId}
`;
}

// Event-driven specs
if (sol.asyncapiYaml) {
  sh += `cat > '${projectDir}/api/asyncapi.yaml' <<'EOFASYNC_${jobId}'
${safeHeredoc(sol.asyncapiYaml, 'EOFASYNC_' + jobId)}
EOFASYNC_${jobId}
`;
}

if (sol.avroSchemasJson) {
  sh += `cat > '${projectDir}/api/avro-schemas.json' <<'EOFAVRO_${jobId}'
${safeHeredoc(JSON.stringify(sol.avroSchemasJson, null, 2), 'EOFAVRO_' + jobId)}
EOFAVRO_${jobId}
`;
}

if (sol.cloudEventsMarkdown) {
  sh += `cat > '${projectDir}/docs/cloud-events.md' <<'EOFCE_${jobId}'
${safeHeredoc(sol.cloudEventsMarkdown, 'EOFCE_' + jobId)}
EOFCE_${jobId}
`;
}

// Database schema
if (sol.sqlSchemaSql) {
  sh += `cat > '${projectDir}/db/schema.sql' <<'EOFSQL_${jobId}'
${safeHeredoc(sol.sqlSchemaSql, 'EOFSQL_' + jobId)}
EOFSQL_${jobId}
`;
}

sh += `
git add '${projectSlug}-docs'
git commit -m 'Add solution architecture for ${projectSlug} (job ${jobId})' || true
git push -u origin '${projectSlug}'
`;

return [{ json: { ...ctx, integrationStyle: sol.integrationStyle, enrichedSequences: enrichedSeq, gitScript: sh } }];

// Build Azure DevOps push payload
const ctx = $("Build Git Script").first().json;
const repoInfo = $("Get Azure Repo Info").first().json;
const branchCheck = $("Check Azure Branch").first().json;
const fileCheck = $json;
const projectSlug = ctx.projectSlug;
const jobId = ctx.jobId;

const artifactContent = ctx.artifactContent || ctx.artifactMarkdown || ctx.content || "";
const artifactPath = "/docs/solution-architecture.md";
const branchName = `refs/heads/${projectSlug}`;

let oldObjectId = "0000000000000000000000000000000000000000";
let changeType = "add";

// Check if branch exists
if (branchCheck.value && branchCheck.value.length > 0) {
  oldObjectId = branchCheck.value[0].objectId;
}

// Check if file exists (statusCode 200 = exists, 404 = doesn't exist)
const fileExists = fileCheck.statusCode === 200;
if (fileExists) {
  changeType = "edit";
} else {
  changeType = "add";
}

const changes = [{
  changeType: changeType,
  item: { path: `/${projectSlug}-docs${artifactPath}` },
  newContent: {
    content: Buffer.from(artifactContent).toString("base64"),
    contentType: "base64encoded"
  }
}];

return [{
  json: {
    ...ctx,
    azurePushPayload: {
      refUpdates: [{ name: branchName, oldObjectId: oldObjectId }],
      commits: [{ comment: `Add solution architecture for ${projectSlug} (job ${jobId})`, changes: changes }]
    },
    azureRepoInfo: repoInfo,
    branchExists: branchCheck.value && branchCheck.value.length > 0,
    fileExists: fileExists,
    changeType: changeType
  }
}];

const ctx = $('Pass Context').first().json;
const sol = $('Validate Solution').first().json;
const enrichedSeq = $('Merge Change Assessment').first().json.enrichedSequencesArtifact || {};
return [{ json: {
  success: true,
  jobId: ctx.jobId,
  projectSlug: ctx.projectSlug,
  stage: 'solution-architecture',
  integrationStyle: sol.integrationStyle,
  enrichedSequences: {
    totalTickets: enrichedSeq.overallSummary?.totalTickets || 0,
    byPriority: enrichedSeq.overallSummary?.byPriority || {},
    byType: enrichedSeq.overallSummary?.byType || {}
  },
  artifacts: {
    solutionArch: ctx.projectSlug + '-docs/docs/solution-architecture.md',
    enrichedSequences: ctx.projectSlug + '-docs/docs/enriched-sequences.json',
    openapi: sol.openapiYaml ? ctx.projectSlug + '-docs/api/openapi.yaml' : null,
    asyncapi: sol.asyncapiYaml ? ctx.projectSlug + '-docs/api/asyncapi.yaml' : null,
    avroSchemas: sol.avroSchemasJson ? ctx.projectSlug + '-docs/api/avro-schemas.json' : null,
    cloudEvents: sol.cloudEventsMarkdown ? ctx.projectSlug + '-docs/docs/cloud-events.md' : null,
    sqlSchema: sol.sqlSchemaSql ? ctx.projectSlug + '-docs/db/schema.sql' : null
  }
} }];

const ctx = $json;
const sequences = ctx.enrichedSequencesArtifact?.enrichedSequences || [];
const internalComponents = new Set(["User", "Admin", "System", "Web App", "API Service", "Database", "Cache", "Frontend", "Backend", "Queue", "Worker"]);
const externalIntegrations = new Set();
const asyncOperations = [];
const integrationEndpoints = [];

for (const seq of sequences) {
  const participants = [...(seq.participants?.internal || []), ...(seq.participants?.external || [])];
  for (const p of participants) {
    const name = p.abstract || p.name || p;
    if (!internalComponents.has(name) && typeof name === "string") {
      const lowerName = name.toLowerCase();
      if (lowerName.includes("service") || lowerName.includes("system") || lowerName.includes("api") || lowerName.includes("provider") || lowerName.includes("external")) {
        externalIntegrations.add(name);
      }
    }
  }
  const ucName = (seq.useCaseName || "").toLowerCase();
  if (ucName.includes("remind") || ucName.includes("notification") || ucName.includes("alert") || ucName.includes("schedule") || ucName.includes("batch") || ucName.includes("async")) {
    asyncOperations.push(seq.useCaseName);
  }
  for (const step of seq.enrichedFlow || []) {
    const fromComp = step.from?.component || "";
    const toComp = step.to?.component || "";
    const action = step.action || step.description || "";
    if (action && (fromComp || toComp)) {
      integrationEndpoints.push({ from: fromComp, to: toComp, action: action, sequence: seq.useCaseName });
    }
    if (fromComp === "System" || toComp === "System") {
      const asyncOp = seq.useCaseName + ": " + action;
      if (!asyncOperations.includes(asyncOp)) { asyncOperations.push(asyncOp); }
    }
    if (!internalComponents.has(fromComp) && fromComp) { externalIntegrations.add(fromComp); }
    if (!internalComponents.has(toComp) && toComp) { externalIntegrations.add(toComp); }
  }
}

const integrationAnalysis = {
  externalIntegrations: Array.from(externalIntegrations),
  asyncOperations: [...new Set(asyncOperations)],
  integrationEndpoints: integrationEndpoints.slice(0, 50),
  summary: { externalSystemCount: externalIntegrations.size, asyncOperationCount: asyncOperations.length, totalEndpointsIdentified: integrationEndpoints.length, sequenceCount: sequences.length, totalSteps: sequences.reduce((sum, s) => sum + (s.enrichedFlow?.length || 0), 0) }
};

console.log("Integration Analysis:", JSON.stringify(integrationAnalysis.summary, null, 2));

return [{ json: { ...ctx, integrationAnalysis } }];
